    static var exceptionsHint: String { L("One per line.", [.ru: "По одному в строке.", .es: "Uno por línea.", .fr: "Un par ligne.", .de: "Eines pro Zeile.", .ja: "1行に1つ。", .zh: "每行一个。", .pt: "Um por linha."]) }
    static var triggers: String { L("When to fix", [.ru: "Когда исправлять", .es: "Cuándo corregir", .fr: "Quand corriger", .de: "Wann korrigieren", .ja: "修正するタイミング", .zh: "何时修正", .pt: "Quando corrigir"]) }
    static var triggersHint: String { L("A word is checked when you finish it this way. Moving the caret or clicking elsewhere never converts — by then you have moved on.", [.ru: "Слово проверяется, когда вы завершили его так. Перемещение курсора или клик в другое место не конвертируют никогда — вы уже ушли дальше.", .es: "La palabra se revisa cuando la terminas así. Mover el cursor o hacer clic en otro sitio nunca convierte: ya te has ido.", .fr: "Le mot est vérifié quand vous le terminez ainsi. Déplacer le curseur ou cliquer ailleurs ne convertit jamais : vous êtes déjà parti.", .de: "Ein Wort wird geprüft, wenn du es so beendest. Cursor bewegen oder woanders klicken konvertiert nie — dann bist du schon weiter.", .ja: "この方法で単語を終えたときに判定します。カーソル移動や他所のクリックでは変換しません。既に離れているためです。", .zh: "以这些方式结束单词时才会判断。移动光标或点击别处从不转换——那时你已经离开了。", .pt: "A palavra é verificada quando você a termina assim. Mover o cursor ou clicar em outro lugar nunca converte — você já saiu."]) }
