    static var noAppsYet: String { L("No apps listed — it works everywhere except terminals and password managers.", [.ru: "Список пуст — работает везде, кроме терминалов и менеджеров паролей.", .es: "Lista vacía: funciona en todas partes salvo terminales y gestores de contraseñas.", .fr: "Liste vide — actif partout sauf terminaux et gestionnaires de mots de passe.", .de: "Liste leer — wirkt überall außer in Terminals und Passwortmanagern.", .ja: "一覧は空です。ターミナルとパスワード管理アプリ以外のすべてで動作します。", .zh: "列表为空——除终端和密码管理器外，在所有位置生效。", .pt: "Lista vazia — funciona em todo lugar, exceto terminais e gerenciadores de senha."]) }
