    static var introSubtitle: String { L("Before it starts changing what you type.", [.ru: "Прежде чем оно начнёт менять набранное вами.", .es: "Antes de que empiece a cambiar lo que escribes.", .fr: "Avant qu’il ne commence à modifier ce que vous tapez.", .de: "Bevor es anfängt, dein Getipptes zu ändern.", .ja: "入力内容を書き換え始める前に。", .zh: "在它开始改动你输入的内容之前。", .pt: "Antes de começar a mudar o que você digita."]) }
    static var introWhat: String { L("Type ghbdtn in the wrong layout and it becomes привет, with the input source switching to match.", [.ru: "Наберёте ghbdtn не в той раскладке — станет привет, и раскладка переключится следом.", .es: "Escribe ghbdtn en la distribución equivocada y se convierte en привет, cambiando también la fuente de entrada.", .fr: "Tapez ghbdtn dans la mauvaise disposition et cela devient привет, la source de saisie suivant.", .de: "Tippe ghbdtn in der falschen Belegung, und es wird привет — die Eingabequelle wechselt mit.", .ja: "誤った配列で ghbdtn と入力すると привет になり、入力ソースも切り替わります。", .zh: "用错误布局输入 ghbdtn 会变成 привет，输入法也随之切换。", .pt: "Digite ghbdtn no layout errado e vira привет, com a fonte de entrada acompanhando."]) }
    static var introWhen: String { L("Only when what you typed is not a word and becomes one after the swap. Anything that is already a word is left alone.", [.ru: "Только если набранное — не слово, а после перекладки становится словом. Всё, что уже слово, не трогается.", .es: "Solo si lo que escribiste no es una palabra y sí lo es tras el cambio. Lo que ya es palabra no se toca.", .fr: "Seulement si ce que vous avez tapé n’est pas un mot et en devient un après conversion. Ce qui en est déjà un reste.", .de: "Nur wenn das Getippte kein Wort ist und nach dem Tausch eines wird. Was schon ein Wort ist, bleibt.", .ja: "入力どおりでは単語でなく、変換すると単語になる場合だけです。すでに単語のものは変更しません。", .zh: "仅当你输入的不是单词、转换后才是单词时。已经是单词的内容不会被改动。", .pt: "Só quando o que você digitou não é palavra e passa a ser após a troca. O que já é palavra fica."]) }
    static var introWhere: String { L("Never in terminals, password fields or password managers — there a strange-looking word is usually the right one.", [.ru: "Никогда в терминалах, полях пароля и менеджерах паролей — там странное на вид слово обычно и есть нужное.", .es: "Nunca en terminales, campos de contraseña ni gestores de contraseñas: allí una palabra rara suele ser la correcta.", .fr: "Jamais dans les terminaux, les champs de mot de passe ni les gestionnaires : un mot étrange y est souvent le bon.", .de: "Nie in Terminals, Passwortfeldern oder Passwortmanagern — dort ist ein seltsames Wort meist das richtige.", .ja: "ターミナル、パスワード欄、パスワード管理アプリでは動作しません。そこでは不自然な語こそ正しいためです。", .zh: "从不在终端、密码框和密码管理器中生效——那里看起来奇怪的词通常正是对的。", .pt: "Nunca em terminais, campos de senha ou gerenciadores de senha — ali uma palavra estranha costuma ser a certa."]) }
    static var introUndo: String { L("Every change can be undone with a shortcut, and any word can be added to a never-change list.", [.ru: "Любую замену можно вернуть горячей клавишей, а любое слово — занести в список «не менять».", .es: "Cada cambio se puede deshacer con un atajo, y cualquier palabra puede ir a la lista de intocables.", .fr: "Chaque changement s’annule par un raccourci, et tout mot peut rejoindre la liste des intouchables.", .de: "Jede Änderung lässt sich per Kurzbefehl zurücknehmen, und jedes Wort kann auf die Nie-ändern-Liste.", .ja: "変更はショートカットで元に戻せ、任意の単語を「変更しない」一覧に追加できます。", .zh: "每次修改都可用快捷键撤销，任何词都能加入「从不修改」列表。", .pt: "Toda mudança pode ser desfeita por atalho, e qualquer palavra pode ir para a lista de intocáveis."]) }
    static var introStart: String { L("Got it", [.ru: "Понятно", .es: "Entendido", .fr: "Compris", .de: "Verstanden", .ja: "了解", .zh: "明白了", .pt: "Entendi"]) }
